import numpy as np
def equation(t, A, params):
    return -(params[0]+params[1]*t+params[2]*t**2)*(A-params[3])

def addfit(Abasis, tbins):
    cols=[A**k for k in range(Abasis+1)]
    tb=np.digitize(t,np.linspace(0.5,10,tbins+1))
    for k in range(1,tbins+1): cols.append((tb==k).astype(float))
    X=np.column_stack(cols); c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]; r=dA_dt-X@c
    return (np.mean(r**2)/np.var(dA_dt)).round(5)
print('additive', addfit(4,10), addfit(6,20))
# multiplicative: r = g(t)*(a+bA+cA^2) -> check via interaction bins
def multfit(Adeg, tbins):
    tb=np.digitize(t,np.linspace(0.5,10,tbins+1))
    cols=[]
    for k in range(1,tbins+1):
        m=(tb==k)
        for d in range(Adeg+1): cols.append(np.where(m,A**d,0.0))
    X=np.column_stack(cols); c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]; r=dA_dt-X@c
    return (np.mean(r**2)/np.var(dA_dt)).round(6)
print('per-bin poly1', multfit(1,10), 'poly2', multfit(2,10), 'poly2 20bins', multfit(2,20))

